INSERT OR IGNORE INTO articles(slug,section,language,title,summary,body,sources_json,status,created_at,updated_at) VALUES ('history-how-historians-use-primary-sources-ar','history','ar','كيف يستخدم المؤرخون المصادر الأولية؟','مدخل إلى الوثائق والشهادات والمصادر الأولية وحدودها.','Primary sources are materials created close to the time or event being studied, such as documents, photographs or contemporary records. They can provide direct evidence but still require context, authentication and comparison with other sources.','[{"title":"Reference","publisher":"BAYAN reference source","url":"https://www.loc.gov/collections/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z');
