INSERT OR IGNORE INTO articles(slug,section,language,title,summary,body,sources_json,status,created_at,updated_at) VALUES ('trends-trend-or-verified-fact-what-is-the-difference-ar','trends','ar','ما الفرق بين الاتجاه الرائج والمعلومة الموثقة؟','فصل ما ينتشر بين الناس عن الخبر أو الحقيقة التي يمكن إثباتها.','A trend signal shows attention or repeated discussion; it does not by itself prove that the underlying claim is true. BAYAN should use trends to discover questions, then verify the claims independently before presenting them as facts.','[{"title":"Reference","publisher":"BAYAN reference source","url":"https://trends.google.com/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z');
