INSERT OR IGNORE INTO articles(slug,section,language,title,summary,body,sources_json,status,created_at,updated_at) VALUES ('trends-how-to-interpret-online-trends-carefully-ar','trends','ar','كيف نقرأ الاتجاهات على الإنترنت بحذر؟','لماذا لا يكفي عدد المشاركات لإثبات أهمية أو صحة موضوع.','Online attention can be affected by algorithms, coordinated activity, breaking events and repetition. A careful trend analysis checks the time window, audience, independent signals and the evidence behind the claim.','[{"title":"Reference","publisher":"BAYAN reference source","url":"https://www.pewresearch.org/internet/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z');
INSERT OR IGNORE INTO articles(slug,section,language,title,summary,body,sources_json,status,created_at,updated_at) VALUES ('trends-how-to-interpret-online-trends-carefully-en','trends','en','How to interpret online trends carefully','Why volume of posts alone does not prove importance or truth.','Online attention can be affected by algorithms, coordinated activity, breaking events and repetition. A careful trend analysis checks the time window, audience, independent signals and the evidence behind the claim.','[{"title":"Reference","publisher":"BAYAN reference source","url":"https://www.pewresearch.org/internet/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z');
INSERT OR IGNORE INTO articles(slug,section,language,title,summary,body,sources_json,status,created_at,updated_at) VALUES ('science-what-is-a-scientific-hypothesis-ar','science','ar','ما هي الفرضية العلمية؟','الفرق بين الفرضية والنظرية والدليل في البحث العلمي.','A scientific hypothesis is a testable proposed explanation. A theory is a broader explanatory framework supported by substantial evidence. Scientific claims become stronger when independent observations and experiments repeatedly support them.','[{"title":"Reference","publisher":"BAYAN reference source","url":"https://science.nasa.gov/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z');
