INSERT OR IGNORE INTO articles(slug,section,language,title,summary,body,sources_json,status,created_at,updated_at) VALUES ('world-what-is-a-demographic-transition-ar','world','ar','ما هو التحول الديموغرافي؟','شرح تغير معدلات المواليد والوفيات مع التنمية والتغير السكاني.','Demographic transition describes a broad pattern in which mortality and fertility rates change as societies develop. Countries can move through the stages at different speeds and with different outcomes.','[{"title":"Reference","publisher":"BAYAN reference source","url":"https://www.un.org/development/desa/pd/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z');
INSERT OR IGNORE INTO articles(slug,section,language,title,summary,body,sources_json,status,created_at,updated_at) VALUES ('world-what-is-a-demographic-transition-en','world','en','What is a demographic transition?','An explanation of changing birth and death rates and population structure.','Demographic transition describes a broad pattern in which mortality and fertility rates change as societies develop. Countries can move through the stages at different speeds and with different outcomes.','[{"title":"Reference","publisher":"BAYAN reference source","url":"https://www.un.org/development/desa/pd/"}]','PUBLISHED','2026-10-06T00:00:00Z','2026-10-06T00:00:00Z');
